package com.toir.service.repair;
import com.toir.dto.repaircampaign.RepairCampaignResourceRequest;
import com.toir.entity.Counteragent;
import com.toir.entity.repair.*;
import com.toir.entity.users.*;
import com.toir.enums.*;
import com.toir.repository.CounteragentRepository;
import com.toir.repository.projects.BrigadeRepository;
import com.toir.repository.repair.*;
import com.toir.repository.users.EmployeeRepository;
import com.toir.security.ScopeAccessService;
import com.toir.util.AuditBuilderService;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;
import java.time.Instant;import java.util.*;
import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class)
class RepairCampaignResourcePolicyTest {
 @Mock RepairCampaignRepository campaigns;@Mock RepairCampaignDepartmentRepository campaignDepartments;@Mock RepairCampaignWorkItemRepository items;@Mock RepairCampaignResourceAssignmentRepository assignments;@Mock EmployeeRepository employees;@Mock BrigadeRepository brigades;@Mock CounteragentRepository counteragents;@Mock com.toir.repository.projects.BrigadeMemberRepository brigadeMembers;@Mock com.toir.repository.users.UserCertificationRepository certifications;@Mock com.toir.repository.CertificationTypeRepository certificationTypes;@Mock ScopeAccessService scope;@Mock AuditBuilderService audit;@InjectMocks RepairCampaignResourcePolicy policy;
 UUID campaignId=UUID.randomUUID(),itemId=UUID.randomUUID(),employeeId=UUID.randomUUID();RepairCampaign campaign;Instant start=Instant.parse("2026-08-01T08:00:00Z"),end=Instant.parse("2026-08-01T12:00:00Z");
 @BeforeEach void setup(){campaign=new RepairCampaign();campaign.setId(campaignId);campaign.setVersion(1L);campaign.setStatus(RepairCampaignStatus.DRAFT);lenient().when(campaigns.findLockedByIdAndIsDeletedFalse(campaignId)).thenReturn(Optional.of(campaign));RepairCampaignWorkItem item=new RepairCampaignWorkItem();item.setId(itemId);lenient().when(items.findByIdAndCampaignIdAndIsDeletedFalse(itemId,campaignId)).thenReturn(Optional.of(item));}
 @Test void rejectsInvalidCardinalityWindowAndInactiveResource(){assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,null,null,null,"A",start,end,null))).hasMessageContaining("EXACTLY_ONE");when(employees.findByIdAndIsDeletedFalseForUpdate(employeeId)).thenReturn(Optional.empty());assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,employeeId,null,null,"A",start,end,null))).hasMessageContaining("INACTIVE");}
 @Test void rejectsMissingCompetencyAndOverlappingResource(){UUID department=UUID.randomUUID();campaign.setDepartmentId(department);Employee e=new Employee();e.setActive(true);e.setDepartmentId(department);e.setPosition("mechanic");when(employees.findByIdAndIsDeletedFalseForUpdate(employeeId)).thenReturn(Optional.of(e));assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,employeeId,null,null,"A",start,end,"welder"))).hasMessageContaining("COMPETENCY_MISSING");RepairCampaignResourceAssignment old=new RepairCampaignResourceAssignment();old.setEmployeeId(employeeId);old.setPlannedStartAt(start);old.setPlannedEndAt(end);when(assignments.findActiveOverlaps(eq(employeeId),isNull(),isNull(),any(),any(),isNull())).thenReturn(List.of(old));assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,employeeId,null,null,"B",start.plusSeconds(60),end.plusSeconds(60),"mechanic"))).hasMessageContaining("RESOURCE_CONFLICT");}
 @Test void criticalBlockerUsesExplicitPriorityOnly(){RepairCampaignWorkItem critical=new RepairCampaignWorkItem();critical.setId(itemId);critical.setPriority(RepairCampaignPriority.CRITICAL);when(assignments.findAllByRepairCampaignIdAndIsDeletedFalseOrderByPlannedStartAtAscIdAsc(campaignId)).thenReturn(List.of());when(items.findAllByCampaignIdAndIsDeletedFalseOrderByOrderNumberAsc(campaignId)).thenReturn(List.of(critical));assertThat(policy.blockers(campaignId)).containsExactly("CRITICAL_WORK_UNASSIGNED:"+itemId);}
 @Test void rejectsBlankShiftInvalidWindowAndInactiveBrigadeOrCounteragent(){assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,employeeId,null,null," ",start,end,null))).hasMessageContaining("WINDOW_INVALID");assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,employeeId,null,null,"A",end,start,null))).hasMessageContaining("WINDOW_INVALID");UUID brigade=UUID.randomUUID(),counteragent=UUID.randomUUID();when(brigades.findByIdAndIsDeletedFalseForUpdate(brigade)).thenReturn(Optional.empty());when(counteragents.findByIdAndIsDeletedFalseForUpdate(counteragent)).thenReturn(Optional.empty());assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,null,brigade,null,"A",start,end,null))).hasMessageContaining("INACTIVE");assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,null,null,counteragent,"A",start,end,null))).hasMessageContaining("INACTIVE");}
 @Test void rejectsCrossCampaignOverlap(){UUID department=UUID.randomUUID();campaign.setDepartmentId(department);Employee e=new Employee();e.setId(employeeId);e.setActive(true);e.setDepartmentId(department);when(employees.findByIdAndIsDeletedFalseForUpdate(employeeId)).thenReturn(Optional.of(e));RepairCampaignResourceAssignment other=new RepairCampaignResourceAssignment();other.setId(UUID.randomUUID());other.setRepairCampaignId(UUID.randomUUID());other.setEmployeeId(employeeId);other.setPlannedStartAt(start);other.setPlannedEndAt(end);when(assignments.findActiveOverlaps(eq(employeeId),isNull(),isNull(),any(),any(),isNull())).thenReturn(List.of(other));assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,employeeId,null,null,"A",start.plusSeconds(60),end.plusSeconds(60),null))).hasMessageContaining("RESOURCE_CONFLICT");}
 @Test void assessmentRevalidatesDeactivatedEmployee(){RepairCampaignResourceAssignment row=new RepairCampaignResourceAssignment();row.setId(UUID.randomUUID());row.setEmployeeId(employeeId);row.setWorkItemId(itemId);row.setPlannedStartAt(start);row.setPlannedEndAt(end);when(assignments.findAllByRepairCampaignIdAndIsDeletedFalseOrderByPlannedStartAtAscIdAsc(campaignId)).thenReturn(List.of(row));when(employees.findByIdAndIsDeletedFalse(employeeId)).thenReturn(Optional.empty());when(items.findAllByCampaignIdAndIsDeletedFalseOrderByOrderNumberAsc(campaignId)).thenReturn(List.of());assertThat(policy.blockers(campaignId)).contains("RESOURCE_INACTIVE:"+row.getId());}
 @Test void foreignDepartmentFailsAsForbiddenBeforeWrite(){campaign.setDepartmentId(UUID.randomUUID());Employee e=new Employee();e.setActive(true);e.setDepartmentId(UUID.randomUUID());when(employees.findByIdAndIsDeletedFalseForUpdate(employeeId)).thenReturn(Optional.of(e));assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,employeeId,null,null,"A",start,end,null))).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);verify(assignments,never()).saveAndFlush(any());}
 @Test void nonOverlappingAdjacentWindowIsAllowedAfterCanonicalLock(){UUID department=UUID.randomUUID();campaign.setDepartmentId(department);Employee e=new Employee();e.setActive(true);e.setDepartmentId(department);when(employees.findByIdAndIsDeletedFalseForUpdate(employeeId)).thenReturn(Optional.of(e));when(assignments.findActiveOverlaps(eq(employeeId),isNull(),isNull(),eq(end),any(),isNull())).thenReturn(List.of());when(assignments.saveAndFlush(any())).thenAnswer(i->{RepairCampaignResourceAssignment x=i.getArgument(0);x.setId(UUID.randomUUID());return x;});when(campaigns.saveAndFlush(campaign)).thenAnswer(i->{campaign.setVersion(2L);return campaign;});assertThat(policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,employeeId,null,null,"A",end,end.plusSeconds(3600),null)).campaignVersion()).isEqualTo(2L);verify(employees).findByIdAndIsDeletedFalseForUpdate(employeeId);}
 @Test void assessmentRevalidatesExpiredCertification(){UUID department=UUID.randomUUID(),user=UUID.randomUUID();campaign.setDepartmentId(department);Employee e=new Employee();e.setActive(true);e.setDepartmentId(department);e.setUserId(user);RepairCampaignResourceAssignment row=new RepairCampaignResourceAssignment();row.setId(UUID.randomUUID());row.setRepairCampaignId(campaignId);row.setEmployeeId(employeeId);row.setWorkItemId(itemId);row.setPlannedStartAt(start);row.setPlannedEndAt(end);row.setCompetencyRequirement("WELDING");com.toir.entity.users.UserCertification cert=new com.toir.entity.users.UserCertification();cert.setTypeCode("WELDING");cert.setStatus("ACTIVE");cert.setExpiresAt(java.time.LocalDate.now().minusDays(1));when(assignments.findAllByRepairCampaignIdAndIsDeletedFalseOrderByPlannedStartAtAscIdAsc(campaignId)).thenReturn(List.of(row));when(employees.findByIdAndIsDeletedFalse(employeeId)).thenReturn(Optional.of(e));when(certifications.findAllByUserIdAndIsDeletedFalse(user)).thenReturn(List.of(cert));when(items.findAllByCampaignIdAndIsDeletedFalseOrderByOrderNumberAsc(campaignId)).thenReturn(List.of());when(assignments.findActiveOverlaps(any(),any(),any(),any(),any(),any())).thenReturn(List.of());assertThat(policy.blockers(campaignId)).contains("COMPETENCY_MISSING:"+row.getId());}
 @Test void assessmentReportsCrossCampaignConflictFromBothCampaignsRegardlessUuidOrdering(){UUID campaignA=UUID.fromString("00000000-0000-0000-0000-000000000010"),campaignB=UUID.fromString("00000000-0000-0000-0000-000000000020"),low=UUID.fromString("00000000-0000-0000-0000-000000000001"),high=UUID.fromString("00000000-0000-0000-0000-000000000099"),department=UUID.randomUUID();RepairCampaignResourceAssignment a=row(low,campaignA),b=row(high,campaignB);Employee e=new Employee();e.setActive(true);e.setDepartmentId(department);when(employees.findByIdAndIsDeletedFalse(employeeId)).thenReturn(Optional.of(e));when(items.findAllByCampaignIdAndIsDeletedFalseOrderByOrderNumberAsc(any())).thenReturn(List.of());when(assignments.findAllByRepairCampaignIdAndIsDeletedFalseOrderByPlannedStartAtAscIdAsc(campaignA)).thenReturn(List.of(a));when(assignments.findAllByRepairCampaignIdAndIsDeletedFalseOrderByPlannedStartAtAscIdAsc(campaignB)).thenReturn(List.of(b));when(assignments.findActiveOverlaps(eq(employeeId),isNull(),isNull(),eq(start),eq(end),eq(low))).thenReturn(List.of(b));when(assignments.findActiveOverlaps(eq(employeeId),isNull(),isNull(),eq(start),eq(end),eq(high))).thenReturn(List.of(a));String blocker="RESOURCE_CONFLICT:"+low+":"+high;assertThat(policy.blockers(campaignA)).containsExactly(blocker);assertThat(policy.blockers(campaignB)).containsExactly(blocker);}
 @Test void assessmentDeduplicatesSameCampaignConflictWithCanonicalPair(){UUID low=UUID.fromString("00000000-0000-0000-0000-000000000001"),high=UUID.fromString("00000000-0000-0000-0000-000000000099"),department=UUID.randomUUID();RepairCampaignResourceAssignment a=row(high,campaignId),b=row(low,campaignId);Employee e=new Employee();e.setActive(true);e.setDepartmentId(department);when(employees.findByIdAndIsDeletedFalse(employeeId)).thenReturn(Optional.of(e));when(items.findAllByCampaignIdAndIsDeletedFalseOrderByOrderNumberAsc(campaignId)).thenReturn(List.of());when(assignments.findAllByRepairCampaignIdAndIsDeletedFalseOrderByPlannedStartAtAscIdAsc(campaignId)).thenReturn(List.of(a,b));when(assignments.findActiveOverlaps(any(),any(),any(),any(),any(),eq(high))).thenReturn(List.of(b));when(assignments.findActiveOverlaps(any(),any(),any(),any(),any(),eq(low))).thenReturn(List.of(a));assertThat(policy.blockers(campaignId)).containsExactly("RESOURCE_CONFLICT:"+low+":"+high);}
 @Test void departmentlessEmployeeAndBrigadeFailClosedOnCreateAndAssessment(){Employee employee=new Employee();employee.setActive(true);UUID brigadeId=UUID.randomUUID();Brigade brigade=new Brigade();brigade.setActive(true);when(employees.findByIdAndIsDeletedFalseForUpdate(employeeId)).thenReturn(Optional.of(employee));when(brigades.findByIdAndIsDeletedFalseForUpdate(brigadeId)).thenReturn(Optional.of(brigade));assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,employeeId,null,null,"A",start,end,null))).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);assertThatThrownBy(()->policy.add(campaignId,new RepairCampaignResourceRequest(1L,itemId,null,brigadeId,null,"A",start,end,null))).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);RepairCampaignResourceAssignment employeeRow=row(UUID.randomUUID(),campaignId),brigadeRow=row(UUID.randomUUID(),campaignId);brigadeRow.setEmployeeId(null);brigadeRow.setBrigadeId(brigadeId);when(assignments.findAllByRepairCampaignIdAndIsDeletedFalseOrderByPlannedStartAtAscIdAsc(campaignId)).thenReturn(List.of(employeeRow,brigadeRow));when(employees.findByIdAndIsDeletedFalse(employeeId)).thenReturn(Optional.of(employee));when(brigades.findByIdAndIsDeletedFalse(brigadeId)).thenReturn(Optional.of(brigade));when(items.findAllByCampaignIdAndIsDeletedFalseOrderByOrderNumberAsc(campaignId)).thenReturn(List.of());assertThat(policy.blockers(campaignId)).containsExactlyInAnyOrder("RESOURCE_SCOPE_INVALID:"+employeeRow.getId(),"RESOURCE_SCOPE_INVALID:"+brigadeRow.getId());verify(assignments,never()).saveAndFlush(any());}
 private RepairCampaignResourceAssignment row(UUID id,UUID owner){RepairCampaignResourceAssignment row=new RepairCampaignResourceAssignment();row.setId(id);row.setRepairCampaignId(owner);row.setEmployeeId(employeeId);row.setWorkItemId(itemId);row.setPlannedStartAt(start);row.setPlannedEndAt(end);return row;}
}
